CREATE TABLE public.service_catalog (id text PRIMARY KEY, name text NOT NULL, category_id text NOT NULL REFERENCES public.directory_categories(id), description text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', archived boolean NOT NULL DEFAULT false, seo jsonb NOT NULL DEFAULT '{}', is_demo boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.service_catalog TO anon; GRANT SELECT,INSERT,UPDATE ON public.service_catalog TO authenticated; GRANT ALL ON public.service_catalog TO service_role;
ALTER TABLE public.service_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_public ON public.service_catalog FOR SELECT TO anon,authenticated USING(NOT archived);
CREATE POLICY catalog_admin ON public.service_catalog FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
INSERT INTO public.service_catalog(id,name,category_id,description,image,is_demo) SELECT DISTINCT ON (v->>'id') v->>'id',v->>'name',v->>'category',COALESCE(v->>'note',''),COALESCE(s.data->>'image',''),s.is_demo FROM public.salons s CROSS JOIN LATERAL jsonb_array_elements(s.data->'services') v WHERE v->>'id' IS NOT NULL AND EXISTS(SELECT 1 FROM public.directory_categories c WHERE c.id=v->>'category') ORDER BY v->>'id',s.created_at;
ALTER TABLE public.directory_categories ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN image text NOT NULL DEFAULT '', ADD COLUMN archived boolean NOT NULL DEFAULT false;
ALTER TABLE public.directory_locations ADD COLUMN archived boolean NOT NULL DEFAULT false;
CREATE TABLE public.support_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, kind text NOT NULL CHECK(kind IN ('contact','problem','account-deletion')), category text NOT NULL CHECK(char_length(category) BETWEEN 2 AND 80), name text NOT NULL DEFAULT '' CHECK(char_length(name)<=100), contact text NOT NULL DEFAULT '' CHECK(char_length(contact)<=255), message text NOT NULL CHECK(char_length(message) BETWEEN 10 AND 2000), related_path text NOT NULL DEFAULT '' CHECK(char_length(related_path)<=300), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','under-review','resolved','closed')), internal_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.support_submissions TO anon; GRANT SELECT,INSERT,UPDATE ON public.support_submissions TO authenticated; GRANT ALL ON public.support_submissions TO service_role;
ALTER TABLE public.support_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_insert ON public.support_submissions FOR INSERT TO anon,authenticated WITH CHECK(status='new' AND internal_note='' AND (user_id IS NULL OR user_id=auth.uid()) AND (kind<>'account-deletion' OR user_id=auth.uid()));
CREATE POLICY support_owner ON public.support_submissions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY support_admin ON public.support_submissions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.user_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, event text NOT NULL, record_id text NOT NULL, message text NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.user_notifications TO authenticated; GRANT ALL ON public.user_notifications TO service_role;
ALTER TABLE public.user_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_owner_read ON public.user_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY notification_owner_update ON public.user_notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.protect_notification_update() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.event IS DISTINCT FROM OLD.event OR NEW.record_id IS DISTINCT FROM OLD.record_id OR NEW.message IS DISTINCT FROM OLD.message OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Only read status may change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_notification BEFORE UPDATE ON public.user_notifications FOR EACH ROW EXECUTE FUNCTION public.protect_notification_update();
CREATE FUNCTION public.notify_review_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('approved','rejected','hidden') THEN INSERT INTO public.user_notifications(user_id,event,record_id,message) VALUES(NEW.user_id,'review-'||NEW.status,NEW.id::text,CASE NEW.status WHEN 'approved' THEN 'نظر شما منتشر شد.' WHEN 'rejected' THEN 'نظر شما منتشر نشد؛ بازخورد بررسی را در نظرهای من ببینید.' ELSE 'نظر شما از نمایش عمومی خارج شد.' END); END IF; IF NEW.reply IS DISTINCT FROM OLD.reply AND COALESCE(NEW.reply,'')<>'' THEN INSERT INTO public.user_notifications(user_id,event,record_id,message) VALUES(NEW.user_id,'review-reply',NEW.id::text,'پاسخ رسمی به نظر شما ثبت شد.'); END IF; RETURN NEW; END $$;
CREATE TRIGGER review_notifications AFTER UPDATE ON public.reviews FOR EACH ROW EXECUTE FUNCTION public.notify_review_event();
CREATE FUNCTION public.notify_report_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.resolved AND NOT OLD.resolved THEN INSERT INTO public.user_notifications(user_id,event,record_id,message) VALUES(NEW.user_id,'report-resolved',NEW.review_id::text,'رسیدگی به گزارش نظر شما پایان یافت.'); END IF; RETURN NEW; END $$;
CREATE TRIGGER report_notifications AFTER UPDATE ON public.review_reports FOR EACH ROW EXECUTE FUNCTION public.notify_report_event();
CREATE TABLE public.site_content (id text PRIMARY KEY, data jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.site_content TO anon; GRANT SELECT,INSERT,UPDATE ON public.site_content TO authenticated; GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY content_public ON public.site_content FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY content_admin ON public.site_content FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.salon_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), salon_id text NOT NULL REFERENCES public.salons(id), storage_path text NOT NULL, label text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected')), internal_note text NOT NULL DEFAULT '', checked_by uuid, checked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.salon_documents TO authenticated; GRANT ALL ON public.salon_documents TO service_role;
ALTER TABLE public.salon_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_admin ON public.salon_documents FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.require_salon_evidence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.data->>'status'='verified' AND (TG_OP='INSERT' OR OLD.data->>'status' IS DISTINCT FROM 'verified') AND NOT EXISTS(SELECT 1 FROM public.salon_documents WHERE salon_id=NEW.id AND status='accepted' AND checked_by IS NOT NULL AND checked_at IS NOT NULL) THEN RAISE EXCEPTION 'Accepted salon evidence required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER salon_evidence BEFORE INSERT OR UPDATE ON public.salons FOR EACH ROW EXECUTE FUNCTION public.require_salon_evidence();
CREATE TRIGGER audit_catalog AFTER INSERT OR UPDATE ON public.service_catalog FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER audit_support AFTER UPDATE ON public.support_submissions FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER audit_documents AFTER INSERT OR UPDATE ON public.salon_documents FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
CREATE TRIGGER audit_content AFTER INSERT OR UPDATE ON public.site_content FOR EACH ROW EXECUTE FUNCTION public.audit_admin_change();
REVOKE ALL ON FUNCTION public.notify_review_event(),public.notify_report_event(),public.require_salon_evidence(),public.protect_notification_update() FROM PUBLIC,anon,authenticated;